const lv_image_dsc_t *product_ui_color_icon_get(product_ui_color_icon_id_t icon_id)
{
    if (icon_id >= PRODUCT_UI_COLOR_ICON_COUNT) {
        return NULL;
    }
    return s_product_ui_color_icons[icon_id];
}
